#define PUNKTFUNK_GAMEPAD_BTN_PADDLE2 131072

#define PUNKTFUNK_GAMEPAD_BTN_PADDLE3 262144

#define PUNKTFUNK_GAMEPAD_BTN_PADDLE4 524288

#define PUNKTFUNK_GAMEPAD_BTN_MISC1 2097152

